package dev.codex.lastzhelper;
public final class RuleTests {
 static int passed;static void expect(boolean value,String name){if(!value)throw new AssertionError(name);passed++;}
 public static void main(String[] args){
  expect(BountyRules.qualifies(12,0,3),"12 boxes");expect(BountyRules.qualifies(15,2,3),"last available loot");expect(!BountyRules.qualifies(15,3,3),"exhausted");expect(!BountyRules.qualifies(6,0,3),"ordinary six");expect(!BountyRules.qualifies(15,-1,3),"unknown loot count");expect(!BountyRules.qualifies(15,0,0),"unknown limit");
  expect(BountyRules.itemQuantity("252006;15|230101;18|200394;1238300|",252006)==15,"box item quantity");expect(BountyRules.itemQuantity("230101;15|252006;12",252006)==12,"ignore unrelated quantity");
  expect(WorldCoordinates.x(1184.9994423153,-1047.3129)==592&&WorldCoordinates.y(-1047.3129)==604,"even-row camera position");expect(WorldCoordinates.x(1189.9994399622,-1010.93985)==594&&WorldCoordinates.y(-1010.93985)==583,"odd-row camera position");
  expect(TruckRules.classify(4,3,439999999).equals("ALERT_TARGET"),"below 440M");expect(TruckRules.classify(5,3,440000000).equals("WORLD_SHARE_ELIGIBLE"),"exactly 440M");expect(TruckRules.classify(5,3,522170000).equals("WORLD_SHARE_ELIGIBLE"),"522.17M");expect(TruckRules.classify(4,2,900000000).equals("WORLD_SHARE_ELIGIBLE"),"two fragments at high power");expect(TruckRules.classify(4,2,0).equals("WORLD_SHARE_ELIGIBLE"),"two fragments at unknown power");expect(TruckRules.classify(4,3,0).equals("UNKNOWN"),"unknown power for 3+");expect(TruckRules.classify(3,5,100).equals("SKIP_GRADE"),"wrong grade");expect(TruckRules.classify(5,1,100).equals("SKIP"),"one slot not quantity");
  expect(!TruckRules.shareAllowed(17,17),"excluded truck state");expect(TruckRules.shareAllowed(18,17),"other state still shares");expect(TruckRules.shareAllowed(17,0),"disabled state filter");expect(TruckRules.parseSkipState("")==0,"blank disables filter");expect(TruckRules.parseSkipState(" 17 ")==17,"typed state");
  boolean invalid=false;try{TruckRules.parseSkipState("-1");}catch(IllegalArgumentException e){invalid=true;}expect(invalid,"reject negative skip state");
  expect(TruckRules.classify(4,3,249999999,250000000).equals("ALERT_TARGET"),"custom attack limit");expect(TruckRules.classify(4,3,250000000,250000000).equals("WORLD_SHARE_ELIGIBLE"),"custom limit boundary shares");expect(TruckRules.classify(4,2,200000000,250000000).equals("WORLD_SHARE_ELIGIBLE"),"two slots still share below custom limit");
  expect(TruckRules.summary(154290783).equals("154m"),"power-only message");expect(TruckRules.summary(154800000).equals("155m"),"rounded power-only message");expect(TruckRules.parsePowerLimit("440")==440,"default limit parsing");
  invalid=false;try{TruckRules.parsePowerLimit("0");}catch(IllegalArgumentException e){invalid=true;}expect(invalid,"reject zero attack limit");
  String windows="  Window #0 Window{abc1 u0 com.readygo.barrel.gp/Game}:\n    mSession=Session{a 111:u0a222}\n  Window #1 Window{abc u0 com.readygo.barrel.gp/Game}:\n    mSession=Session{b 222:u0a221}\n  Window #2 Window{def u0 Helper}:\n    mSession=Session{c 333:u0a223}\n  mCurrentFocus=Window{abc u0 com.readygo.barrel.gp/Game}\n";
  expect(ProcessWindows.focusedPid(windows).equals("222"),"select focused clone when titles match and window tokens share a prefix");
  expect(ProcessWindows.focusedPid(windows.replace("mCurrentFocus=Window{abc ","mCurrentFocus=Window{def ")).equals("333"),"helper focus cannot be treated as game focus");
  expect(ProcessWindows.focusedPid(windows.replace("mCurrentFocus=Window{abc ","mCurrentFocus=Window{unknown ")).isEmpty(),"unresolved focused window stops native input");
  expect(ProcessWindows.focusedPid("mCurrentFocus=null").isEmpty(),"no focus stops native input");
  expect(TruckPolicy.classify("truck-dm",5,2,100000000,440000000).equals("SKIP"),"DM ignores two slots");
  expect(TruckPolicy.classify("truck-dm",4,3,439999999,440000000).equals("PRIVATE_SHARE_ELIGIBLE"),"DM three slots below limit");
  expect(TruckPolicy.classify("truck-dm",5,4,440000000,440000000).equals("SKIP"),"DM excludes equality");
  expect(TruckPolicy.classify("truck-dm",5,3,0,440000000).equals("UNKNOWN"),"DM unknown power stops");
  expect(TruckPolicy.classify("truck-world",5,3,100000000,440000000).equals("WORLD_SHARE_ELIGIBLE"),"share-only never attacks low-power three slots");
  expect(TruckPolicy.classify("truck-world",4,2,900000000,440000000).equals("WORLD_SHARE_ELIGIBLE"),"share-only two slots at any power");
  expect(TruckPolicy.classify("truck-attack",4,2,100000000,440000000).equals("SKIP"),"attack-only ignores two slots");
  expect(TruckPolicy.classify("truck-attack",5,3,100000000,440000000).equals("ALERT_TARGET"),"attack-only matches three below limit");
  expect(!TruckPolicy.accountAllowed("truck-attack","2059765822000064"),"farm cannot use main attack mode");
  expect(TruckPolicy.accountAllowed("truck-attack",TruckPolicy.MAIN_UID),"Gaarix may attack");
  expect(TruckPolicy.accountAllowed("truck-dm",TruckPolicy.MAIN_UID),"Gaarix can post to its trucks group");
  expect(TruckPolicy.accountAllowed("truck-world",TruckPolicy.MAIN_UID),"main remains allowed for world mode");
  String truck="1430458491209784193";
  expect(LinkRules.containsTruck("<link=eyJpZCI6IjE0MzA0NTg0OTEyMDk3ODQxOTMifQ==>",truck),"base64 truck link identity");
  expect(LinkRules.containsTruck("https://example.invalid/?id="+truck,truck),"plain truck link identity");
  expect(!LinkRules.containsTruck("https://example.invalid/?id=9999999999999999999",truck),"different truck rejected");
  expect(LinkRules.coordinates("[DSKI]Anas Bond [#:51 X:777 Y:417]","Anas Bond","DSKI",51,777,417),"actual copied coordinate format");
  expect(!LinkRules.coordinates("[DSKI]Anas Bond [#:51 X:777 Y:417]","Anas Bond","DSKI",51,777,418),"different copied location rejected");
  expect(!LinkRules.coordinates("[DSKI]Other [#:51 X:777 Y:417]","Anas Bond","DSKI",51,777,417),"different copied owner rejected");
  expect(TruckPolicy.classifyTwoFragmentTest(4,2,100,440000000).equals("ALERT_TARGET"),"explicit two-slot test allowed");
  expect(TruckPolicy.classifyTwoFragmentTest(5,1,100,440000000).equals("SKIP"),"test still rejects one slot");
  expect(TruckPolicy.classifyTwoFragmentTest(5,2,440000000,440000000).equals("SKIP"),"test keeps strict power cap");
  expect(TruckPolicy.classifyTwoFragmentTest(3,2,100,440000000).equals("SKIP_GRADE"),"test keeps grade rule");
  expect(TruckPolicy.classify("truck-attack",4,2,100,440000000).equals("SKIP"),"normal attack remains three slots");
  expect(TruckPolicy.classify("truck-dm",4,2,100,440000000).equals("SKIP"),"group rule remains three slots");
  expect(TruckPolicy.classifySelectedTest(5,1,431761893,440000000,1).equals("ALERT_TARGET"),"explicit selected one-slot truck allowed");
  expect(TruckPolicy.classifySelectedTest(5,0,100,440000000,1).equals("SKIP"),"selected test keeps declared slot minimum");
  expect(TruckPolicy.classify("truck-attack",5,1,431761893,440000000).equals("SKIP"),"selected exception does not change production rules");
  expect(BountyRoute.known("bounties")&&BountyRoute.known("bounties-group")&&!BountyRoute.known("truck-dm"),"exclusive bounty modes");
  expect(BountyRoute.key(false,"room","uuid").equals("bounty:uuid"),"preserve existing World bounty history");
  expect(!BountyRoute.key(true,"room","uuid").equals(BountyRoute.key(false,"room","uuid")),"group history independent of World");
  expect(!BountyRoute.key(true,"room","uuid").equals(BountyRoute.key(true,"other","uuid")),"group history bound to room");
  expect(BountyRoute.checkpoint(false,false).equals("bounty-progress.json")&&BountyRoute.checkpoint(false,true).equals("bounty-progress-dry.json"),"preserve World checkpoints");
  expect(BountyRoute.checkpoint(true,false).equals("bounty-group-progress.json")&&!BountyRoute.checkpoint(true,false).equals(BountyRoute.checkpoint(true,true)),"separate group and preview progress");
  expect(!CombatPolicy.allowed("truck-dm",TruckPolicy.MAIN_UID)&&!CombatPolicy.allowed("truck-world",TruckPolicy.MAIN_UID)&&!CombatPolicy.allowed("bounties-group",TruckPolicy.MAIN_UID),"sharing modes reject combat even on main");
  expect(!CombatPolicy.allowed("truck-attack","2059765822000064")&&CombatPolicy.allowed("truck-attack",TruckPolicy.MAIN_UID),"only explicit attack mode on Gaarix permits combat");
  expect(CombatPolicy.protectedControl("UIManagerInstance/windows/UILWTrainScene/View/infoPanel/goBtn","")&&CombatPolicy.protectedControl("UIManagerInstance/windows/UIWorldPoint/View/buildBtnCells/#1/btn",""),"both Plunder stages protected");
  expect(CombatPolicy.protectedControl("UIManagerInstance/windows/UIPVEScene/View/btn_start","")&&!CombatPolicy.protectedControl("UIManagerInstance/windows/UILWTrainScene/View/infoPanel/shareBtn",""),"Fight protected, blue Share remains available");
  expect(TruckPolicy.known("truck-world-3"),"three-plus World mode accepted");
  expect(TruckPolicy.classify("truck-world-3",4,2,100000000,440000000).equals("SKIP"),"three-plus World skips two slots");
  expect(TruckPolicy.classify("truck-world-3",4,3,100000000,440000000).equals("WORLD_SHARE_ELIGIBLE"),"three-plus World shares below power limit");
  expect(TruckPolicy.classify("truck-world-3",5,4,900000000,440000000).equals("WORLD_SHARE_ELIGIBLE"),"three-plus World shares four slots above power limit");
  expect(TruckPolicy.classify("truck-world-3",3,3,100000000,440000000).equals("SKIP_GRADE"),"three-plus World excludes other grades");
  expect(TruckPolicy.classify("truck-world-3",5,3,0,440000000).equals("UNKNOWN"),"three-plus World requires known power");
  expect(TruckPolicy.accountAllowed("truck-world-3",TruckPolicy.MAIN_UID)&&!CombatPolicy.allowed("truck-world-3",TruckPolicy.MAIN_UID),"main can share three-plus without combat permission");
  expect(TruckPolicy.unavailableCell(false,"native_pre_dispatch","ui-tap","Error: Exported control is hidden"),"hidden truck cell can refresh before input");
  expect(TruckPolicy.unavailableCell(false,"native_pre_dispatch","ui-tap","Error: Control is outside visible screen"),"offscreen truck cell can refresh before input");
  expect(!TruckPolicy.unavailableCell(true,"native_pre_dispatch","ui-tap","Error: Exported control is hidden"),"possible input prevents cell retry");
  expect(!TruckPolicy.unavailableCell(false,"input_started","ui-tap","Error: Exported control is hidden"),"wrong phase prevents retry");
  expect(!TruckPolicy.unavailableCell(false,"native_pre_dispatch","ui-bounds","Error: Exported control is hidden"),"wrong action prevents retry");
  expect(!TruckPolicy.unavailableCell(false,"native_pre_dispatch","ui-tap","No Unity render callback; no click sent"),"frozen renderer remains a stop");
  expect(!TruckPolicy.unavailableCell(false,"native_pre_dispatch","ui-tap","Error: Selected character changed; input rejected"),"account change remains a stop");
  System.out.println("Passed "+passed+" rule tests");
 }
}
